{"l":6,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer i sætningen: 'Vi bor i et ___.'","o":["hus","bil","stol","skole"],"a":"hus","r":"Det hedder et hus. Bil, stol og skole hedder en, så de kan ikke stå efter 'et'."},
{"l":30,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvordan begynder mange eventyr?","o":["Kære dagbog","Der var engang","I dag er det mandag","Tak for sidst"],"a":"Der var engang","r":"'Der var engang' er den klassiske begyndelse på et eventyr. Ordene fortæller, at historien foregår for længe siden."},
{"l":47,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et dyr med fjer og vinger. Hvordan staves det?","o":["fugel","fuul","fugl","fuhl"],"a":"fugl","r":"Ordet skrives med et g, som ikke kan høres. Bogstaverne g og l står lige efter hinanden."},
{"l":66,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sofie går til svømning hver tirsdag. Om torsdagen går hun til spejder.' Hvornår går Sofie til svømning?","o":["Om torsdagen","Om mandagen","Om lørdagen","Om tirsdagen"],"a":"Om tirsdagen","r":"Der står 'hver tirsdag' lige efter svømning. Torsdag er dagen for spejder."},
{"l":87,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er lavet ud fra ordet 'sne'?","o":["snemand","snegl","snor","snit"],"a":"snemand","r":"En snemand er en figur af sne. Snegl og snor begynder med de samme bogstaver, men har intet med sne at gøre."},
{"l":108,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Sætningen 'Hvad er klokken' spørger om noget. Hvad hedder det tegn, den skal slutte med?","o":["kolon","spørgsmålstegn","punktum","komma"],"a":"spørgsmålstegn","r":"Når man spørger om noget, sætter man spørgsmålstegn til sidst. Punktum bruger man, når man fortæller."},
{"l":127,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mor tænder et lys og tager tæpper frem. Strømmen er lige gået, siger far. Han finder en lommelygte.' Hvad har mor nok tændt?","o":["Fjernsynet","Komfuret","Et stearinlys","Loftslampen"],"a":"Et stearinlys","r":"Når strømmen er gået, virker lamper og fjernsyn ikke. Mor må derfor have tændt et stearinlys."},
{"l":147,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Det regner meget. Hvad tager du på fødderne for at holde dem tørre?","o":["sandaler","badetøfler","hjemmesko","gummistøvler"],"a":"gummistøvler","r":"Gummi lukker ikke vand ind. Derfor bliver fødderne tørre i gummistøvler, også i en vandpyt."},
{"l":169,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Forår, sommer, efterår og vinter er navne på noget. Hvad?","o":["årstider","måneder","ugedage","helligdage"],"a":"årstider","r":"Et år har fire årstider. Januar og maj er derimod navne på måneder."},
{"l":187,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Pindsvinet sover hele vinteren. Om foråret vågner det og leder efter mad.' Hvad gør pindsvinet om vinteren?","o":["Det leder efter mad","Det sover","Det flyver mod syd","Det bygger rede"],"a":"Det sover","r":"Teksten siger, at pindsvinet sover hele vinteren. Først om foråret leder det efter mad."},
{"l":206,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du børster den hver aften, og den sidder i munden. Hvilken stavemåde er rigtig?","o":["tann","tandt","tand","tannd"],"a":"tand","r":"Ordet ender på nd med stumt d. Der er kun ét n."},
{"l":228,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå efter ordene, når træneren råber: 'Løb hurtigere'?","o":["punktum","komma","kolon","udråbstegn"],"a":"udråbstegn","r":"Træneren råber en besked. Et råb slutter med udråbstegn."},
{"l":247,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig for det modsatte af stor?","o":["lille","lile","lilli","lilæ"],"a":"lille","r":"I'et er kort, så der skal to l'er. Ordet slutter på e."},
{"l":266,"g":3,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find udsagnsordet: 'Mormor bager en kage.'","o":["kage","bager","Mormor","en"],"a":"bager","r":"Her fortæller 'bager', hvad mormor gør, så det er et udsagnsord: at bage."},
{"l":289,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det lille grå dyr, som katten jager. Vælg den rigtige stavemåde.","o":["muss","muus","mus","muz"],"a":"mus","r":"U'et er langt, og ordet ender på ét s."},
{"l":306,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et stort dyr, du kan ride på. Find den rigtige stavemåde.","o":["hesst","hesd","hæsd","hest"],"a":"hest","r":"Ordet skrives med e og slutter på st."},
{"l":326,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Omar skal købe mælk for far. Han får en seddel med hen til købmanden. Da han kommer hjem, står der boller på bordet.' Hvor går Omar hen?","o":["Til købmanden","Til sin ven","Til bageren","Til skolen"],"a":"Til købmanden","r":"Der står, at han går hen til købmanden. Bollerne står derhjemme, da han kommer tilbage."},
{"l":347,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvidt og koldt, og det falder ned fra himlen om vinteren. Hvilket ord er stavet rigtigt?","o":["snee","sne","snæ","sneh"],"a":"sne","r":"Ordet er kort og skrives med ét e."},
{"l":369,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lærke sætter sig ved bordet med en pose mel, en skål og tre æg. Mor tænder ovnen.' Hvad skal de nok lave?","o":["Vaske op","Pakke madpakker","Bage","Vande blomster"],"a":"Bage","r":"Mel, æg og en tændt ovn er det, man bruger, når man bager."},
{"l":387,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Frøen lægger sine æg i vand. Af æggene kommer haletudser. Haletudserne bliver senere til små frøer.' Hvad kommer der ud af frøens æg?","o":["Små frøer","Små fisk","Små snegle","Haletudser"],"a":"Haletudser","r":"Teksten siger, at der kommer haletudser af æggene. Først senere bliver de til frøer."},
{"l":406,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Tallet, der kommer efter elleve. Hvordan staves det?","o":["tolv","tolw","tolf","tolu"],"a":"tolv","r":"V'et til sidst er stumt, men det skal skrives. Sådan er det også i 'halv'."},
{"l":424,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Læge, lærer og buschauffør er eksempler på noget. Hvad?","o":["hobbyer","job","sportsgrene","arbejdspladser"],"a":"job","r":"Det er noget, man arbejder med og får løn for. Derfor er de job, ikke hobbyer."},
{"l":447,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Den er flettet, og du kan samle svampe i den. Hvilket ord er stavet rigtigt?","o":["kurw","kurf","kurv","kurrv"],"a":"kurv","r":"Ordet ender på rv, og v'et høres kun svagt."},
{"l":465,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mikkel ville gerne se fjernsyn, men han skulle først rydde op. Hans værelse så ud, som om en storm havde været der.' Hvordan så værelset ud?","o":["Der var meget koldt","Vinduet var gået i stykker","Der var helt nymalet","Der var meget rodet"],"a":"Der var meget rodet","r":"'Som om en storm havde været der' er en måde at sige, at der er rod overalt. Derfor skal han rydde op."},
{"l":487,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er udsagnsleddet i sætningen: 'Far vasker bilen i indkørslen.'","o":["vasker","Far","bilen","i indkørslen"],"a":"vasker","r":"Udsagnsleddet er det ord, der fortæller, hvad der sker. Her er det 'vasker'."},
{"l":507,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord hører til samme ordfamilie som 'synge'?","o":["seng","sang","sand","sø"],"a":"sang","r":"Det, man synger, er en sang. Ord i samme familie kan skifte vokal, som synge, sang og sunget."},
{"l":526,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er et fællesnavn: 'Aya og Rasmus fodrer ænderne i Silkeborg.'","o":["Aya","Rasmus","ænderne","Silkeborg"],"a":"ænderne","r":"Fællesnavne er navne på en hel slags ting eller dyr. De andre ord er navne på bestemte personer og en by."},
{"l":544,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Egernet ___ sine nødder i jorden, så det har mad til vinteren.'","o":["spiser","knækker","taber","gemmer"],"a":"gemmer","r":"Når man gemmer noget, lægger man det et sted, så man kan finde det senere."},
{"l":565,"g":3,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er rigtigt: 'Sidste år ___ vi i Sverige på ferie.'","o":["var","er","være","været"],"a":"var","r":"'Sidste år' er fortid, så det skal være datid. Datid af 'at være' er 'var'."},
{"l":588,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'På mandag skal ahmed til tandlægen.'?","o":["mandag","ahmed","skal","tandlægen"],"a":"ahmed","r":"Ahmed er et navn og skal have stort bogstav. Ugedage som mandag skrives med lille inde i en sætning."},
{"l":604,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'doven'?","o":["klog","modig","flittig","venlig"],"a":"flittig","r":"Den, der er doven, gider ikke lave noget. Den, der er flittig, arbejder godt og længe."},
{"l":627,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'rask' her: 'Emil var syg i går, men nu er han rask igen.'","o":["hurtig","træt","stille","frisk"],"a":"frisk","r":"Rask kan betyde hurtig, men her betyder det, at Emil ikke er syg mere. Han er frisk."},
{"l":647,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du har den på hånden, når det fryser. Hvordan staves den?","o":["handske","hanske","hantske","handsske"],"a":"handske","r":"Der står et stumt d midt i ordet, ligesom i 'hånd'."},
{"l":664,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Rummet, hvor man laver mad. Hvilket ord er stavet rigtigt?","o":["køken","køkken","køkkenn","kjøkken"],"a":"køkken","r":"Vokalen ø er kort, så der skal to k'er i midten. Til sidst står ét n."},
{"l":684,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning har komma rigtigt i opremsningen af kæledyr?","o":["Vi har, en hund en kat og en fisk.","Vi har en hund en kat, og en fisk.","Vi har en hund, en kat og en fisk.","Vi har en hund, en kat, og, en fisk."],"a":"Vi har en hund, en kat og en fisk.","r":"Kommaet står mellem de ting, man opremser. Det sidste dyr kommer efter 'og', og der skal ikke komma foran 'og'."},
{"l":707,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Regnormen graver gange i jorden. Gangene giver luft og plads til planternes rødder. Derfor er regnorme gode for haven.' Hvorfor er regnorme gode for haven?","o":["Fordi de spiser snegle","Fordi de vander planterne","Fordi de bestøver blomsterne","Fordi de giver luft i jorden"],"a":"Fordi de giver luft i jorden","r":"Teksten siger, at gangene giver luft og plads til rødderne. Det hjælper planterne."},
{"l":725,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Valdemar stod længe og kiggede på den høje klatrevæg. Så tog han hjelm på og begyndte at klatre, selvom han rystede lidt.' Hvilket ord passer bedst på Valdemar?","o":["Modig","Doven","Uhøflig","Gnaven"],"a":"Modig","r":"Han er lidt bange, men klatrer alligevel. Det er det, der kaldes at være modig."},
{"l":747,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'nød' her: 'Skibet var i nød ude på havet.'","o":["en hård frugt","stor fare","høje bølger","tæt tåge"],"a":"stor fare","r":"Er man i nød, har man brug for hjælp, fordi noget er farligt. En nød er også noget, egern spiser."},
{"l":764,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig for dagen før torsdag?","o":["onsdaw","ondsdag","onsdag","ohnsdag"],"a":"onsdag","r":"Ugedagen har intet d efter n. Ordet slutter på -dag."},
{"l":785,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Der var kun ét stykke kage tilbage. Filip kiggede på sin søster Ronja og skar det i to. Ronja fik det største stykke.' Hvad viser teksten om Filip?","o":["At han er god til at bage","At han er sulten","At han er nærig","At han er rar mod sin søster"],"a":"At han er rar mod sin søster","r":"Han deler den sidste kage og giver hende det største stykke. Det er en rar ting at gøre."},
{"l":806,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Årets korteste måned. Hvilken stavemåde er rigtig?","o":["februar","febuar","februa","februær"],"a":"februar","r":"Husk r'et efter b, og at der slutter med -uar."},
{"l":825,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form har navneordet 'lamper'?","o":["bestemt flertal","ubestemt flertal","ubestemt ental","bestemt ental"],"a":"ubestemt flertal","r":"Der er flere end én lampe, men ikke nogle bestemte. Den bestemte form hedder 'lamperne'."},
{"l":846,"g":3,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Nu var det Benjamins tur. Han gik langsomt hen til tavlen, mens han kiggede ned i gulvet. Han håbede, at klokken snart ville ringe.' Hvad ønsker Benjamin?","o":["At han bliver den første ved tavlen","At han får flere opgaver på tavlen","At han slipper for at stå ved tavlen","At han får hjælp af sin sidemand"],"a":"At han slipper for at stå ved tavlen","r":"Han går langsomt og håber på klokken, for så slipper han. Han har ikke lyst til at stå ved tavlen."},
{"l":864,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler: 'Far ___ kaffe hver morgen.'","o":["drikke","driker","drigger","drikker"],"a":"drikker","r":"I'et er kort, så der skal to k'er, og nutid får -r til sidst."},
{"l":882,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er man, når noget sker, som man slet ikke havde ventet?","o":["overrasket","nysgerrig","lettet","flov"],"a":"overrasket","r":"En overraskelse er noget, man ikke vidste ville ske. Så bliver man overrasket."},
{"l":904,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'fortryde' noget?","o":["at glæde sig til, at det skal ske","at ønske, man havde gjort noget andet","at gøre det samme en gang til","at fortælle det til en god ven"],"a":"at ønske, man havde gjort noget andet","r":"Fortryder man, er man ked af noget, man har gjort, og ville ønske, man havde gjort noget andet."},
{"l":924,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Leo havde lånt Bjørns skateboard og slået en stor ridse i det. Han kunne ikke spise sin aftensmad, for han tænkte hele tiden på, hvad han skulle sige.' Hvad føler Leo?","o":["Glæde over skateboardet","Lyst til at køre mere","Dårlig samvittighed","Vrede på Bjørn"],"a":"Dårlig samvittighed","r":"Han har ødelagt noget, han har lånt, og kan ikke spise. Det er dårlig samvittighed."},
{"l":947,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler: 'Jeg ___ glasset på bordet nu.'","o":["sidder","sætte","sæter","sætter"],"a":"sætter","r":"Du flytter glasset, så her skal 'sætter' stå. Ordet har to t'er og nutids-r."},
{"l":964,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Der var ___ børn til festen.'","o":["mange","mannge","mangge","maange"],"a":"mange","r":"Ordet skrives med ng i midten og kun ét g."},
{"l":985,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Teo blev ved med at sparke til muren. Bolden kom tilbage hver gang, og efter en time kunne han ramme den samme sten ti gange i træk.' Hvad viser teksten om Teo?","o":["At han ikke må sparke til muren","At han bliver bedre, når han øver","At han er ved at blive træt af at øve","At bolden er ved at gå i stykker"],"a":"At han bliver bedre, når han øver","r":"Teksten viser, at han efter en times øvelse kan ramme præcist. Øvelse gør ham dygtigere."},
{"l":1006,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den korrekte stavemåde: 'Det er en ___ god idé.'","o":["rikti","rigti","rigtig","riktig"],"a":"rigtig","r":"Ordet skrives med gt i midten og slutter på -ig, selvom det sidste g ikke kan høres."},
{"l":1022,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'En stor haj kan være ___ for mennesker.'","o":["farli","farrlig","farlik","farlig"],"a":"farlig","r":"Ordet ender på -lig med stumt g. Der er kun ét r."},
{"l":1045,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vi glemmer tit at takke Lone. Hun tørrer bordene af i kantinen, tømmer skraldespandene og smiler til alle. Uden hende ville skolen se slem ud.' Hvad vil forfatteren sige?","o":["At Lone gør et vigtigt arbejde","At kantinen serverer dårlig mad","At eleverne er glade for skolen","At skraldespandene er for små"],"a":"At Lone gør et vigtigt arbejde","r":"Teksten roser Lone: Vi burde takke hende, og skolen ville se slem ud uden hende."},
{"l":1064,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord mangler: 'Der lød en ___ lyd fra loftet.'","o":["merkelig","mærkelig","mærkeli","mærkelich"],"a":"mærkelig","r":"Ordet skrives med æ og ender på -lig med stumt g."},
{"l":1085,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord i sætningen skal stå med stort: 'På lørdag tager vi færgen til bornholm.'","o":["lørdag","færgen","bornholm","tager"],"a":"bornholm","r":"Bornholm er navnet på en ø og skal have stort begyndelsesbogstav. Ugedage skrives med småt på dansk."},
{"l":1106,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Et farverigt insekt med store vinger, som flyver fra blomst til blomst. Hvordan staves det?","o":["somerfugl","sommerful","sommer fugl","sommerfugl"],"a":"sommerfugl","r":"Sammensatte ord skrives i ét ord. Husk to m'er og det stumme g."},
{"l":1123,"g":3,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvert år samler klasserne skrald på stranden. I år fandt de mest plast: flasker, poser og gamle fiskenet. Plast forsvinder ikke af sig selv og kan skade fugle og fisk.' Hvad fandt klasserne mest af?","o":["Plast","Fiskeben","Glas","Papir"],"a":"Plast","r":"Der står 'mest plast', og flasker, poser og fiskenet er eksempler på det."},
{"l":1144,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er man, når man sætter stor pris på det, nogen har gjort for en?","o":["misundelig","taknemmelig","skuffet","ligeglad"],"a":"taknemmelig","r":"Den, der er taknemmelig, vil gerne sige tak, fordi andre har været gode ved en."},
{"l":1164,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det, du har med hjemmefra og spiser i spisefrikvarteret. Hvilket ord er stavet rigtigt?","o":["matpakke","madpake","madpakke","mad pakke"],"a":"madpakke","r":"Ordet består af 'mad' og 'pakke'. Det skrives i ét ord med to k'er."},
{"l":1184,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Laura sagde, at hun gerne ville hjælpe med opvasken. Far kiggede på hende med store øjne. Så spurgte hun, om hun måtte få lov at komme med til koncerten.' Hvorfor tilbød Laura at hjælpe?","o":["Hun elskede at vaske op","Hun skulle øve sig på at tørre af","Far havde bedt hende om det","Hun ville have noget af far"],"a":"Hun ville have noget af far","r":"Lige efter sit tilbud beder hun om lov til koncerten. Hjælpen skulle gøre far venlig. Fars overraskelse viser, at hun ikke plejer at tilbyde det."},
{"l":1204,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord passer: 'Det er ___ at tage cykelhjelm på, når man cykler.'","o":["fornuftigt","ulovligt","umuligt","usynligt"],"a":"fornuftigt","r":"Noget er fornuftigt, når det er klogt at gøre. Hjelmen passer på hovedet, hvis man vælter."},
{"l":1227,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Læreren deler kagen, så alle får lige meget. Hvilket ord passer på det?","o":["frivilligt","retfærdigt","umuligt","farligt"],"a":"retfærdigt","r":"Noget er retfærdigt, når alle bliver behandlet ens, og ingen får mere end de andre."},
{"l":1242,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket udtryk er det modsatte af 'forsvinde'?","o":["lægge sig","gå i stå","dukke op","falde ned"],"a":"dukke op","r":"Det, der forsvinder, er pludselig væk. Det, der dukker op, er pludselig kommet til syne."},
{"l":1264,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det søde, brune slik, der laves af kakao. Hvordan staves det?","o":["sjokolade","chokolate","shokolade","chokolade"],"a":"chokolade","r":"Ordet begynder med ch, som lyder som sj. Det slutter på -lade."},
{"l":1284,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Nora viser sin tegning frem og spørger om noget. Hvilken sætning er skrevet rigtigt?","o":["Nora spurgte: »Er min tegning flot?«","Nora spurgte: »Er min tegning flot.«","Nora spurgte? »Er min tegning flot.«","Nora spurgte. »Er min tegning flot?«"],"a":"Nora spurgte: »Er min tegning flot?«","r":"Der skal kolon efter 'spurgte'. Spørgsmålstegnet hører til det, Nora spørger om, så det står inde i anførselstegnene."},
{"l":1306,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form er rigtig: 'De ___ måger skreg på havnen.'","o":["sulten","sultne","sultent","sult"],"a":"sultne","r":"Foran flere måger får tillægsordet -e, og e'et i midten falder væk: sultne."},
{"l":1323,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Natteravnen Rufus er en kat, der sover hele dagen. Når alle andre går i seng, vågner den og går på jagt i haven.' Hvorfor kaldes katten en natteravn?","o":["Fordi den er sort som en ravn","Fordi den spiser fugle i haven","Fordi den er vågen om natten","Fordi den kan flyve"],"a":"Fordi den er vågen om natten","r":"En natteravn er en, der er oppe om natten. Det passer på Rufus, som sover om dagen. Teksten siger intet om farven."},
{"l":1345,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg tillægsordet: 'Den glade hund gravede i haven.'","o":["hund","gravede","haven","glade"],"a":"glade","r":"Ordet 'glade' fortæller, hvordan hunden er. 'Gravede' fortæller, hvad den gør."},
{"l":1364,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Det var den ___ is i fryseren.'","o":["sidste","siste","sidsde","sisste"],"a":"sidste","r":"Ordet har stumt d foran st. Det er et af de ord, man må huske."},
{"l":1384,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Et navneord kan få 'en' eller 'et' foran sig. Hvilket af ordene er et navneord?","o":["smuk","vindue","hente","hurtig"],"a":"vindue","r":"Man kan sige 'et vindue'. 'Smuk' og 'hurtig' er tillægsord, og 'hente' er et udsagnsord."},
{"l":1404,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken tekst om turen i zoo har punktummet det rigtige sted?","o":["Vi gik i. Zoo der så vi en løve.","Vi gik i zoo der. Så vi en løve.","Vi gik i zoo. Der så vi en løve.","Vi gik i zoo der så vi. En løve."],"a":"Vi gik i zoo. Der så vi en løve.","r":"Den første sætning slutter efter 'zoo'. Den næste begynder med 'Der' og fortæller, hvad de så."},
{"l":1427,"g":3,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Storebror Jakob fik kørekort i går. Nu står han i indkørslen og pudser mors gamle bil, selvom den allerede er ren. Han fløjter og kigger ned ad vejen efter nogen, han kan vise den til.' Hvad føler Jakob nok?","o":["Han er træt af at pudse bilen","Han er sur over, at bilen er gammel","Han er nervøs for at køre","Han er stolt af sit kørekort"],"a":"Han er stolt af sit kørekort","r":"Han fløjter og vil gerne vise bilen frem. Det gør man, når man er stolt af det, man har klaret."},
{"l":1442,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Vi leger gemmeleg. Du skal ___ dig bag træet.'","o":["skjule","sjule","skjulle","skjuule"],"a":"skjule","r":"Ordet begynder med skj. U'et er langt, så der er kun ét l."},
{"l":1465,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord i sætningen skal skrives med stort: 'Familien rejste til paris i sommerferien.'?","o":["rejste","paris","til","sommerferien"],"a":"paris","r":"Paris er navnet på en by. Ferier som sommerferien er ikke navne og skrives med lille."},
{"l":1485,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning er et råb om hjælp og skal slutte med udråbstegn?","o":["Jeg læser en bog","Vi spiser klokken seks","Hjælp mig, jeg er ved at falde","Bogen ligger på bordet"],"a":"Hjælp mig, jeg er ved at falde","r":"Et råb om hjælp siges med stor kraft og får udråbstegn. De andre sætninger fortæller roligt noget."},
{"l":1503,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hver morgen hentede Malthe æg i hønsegården. En dag lå der ingen æg, og hønsene gemte sig i hjørnet. I sneen uden for hønsegården så han poteaftryk.' Hvad er der nok sket?","o":["Malthe har glemt at fodre hønsene","Hønsene er blevet syge af kulde","Hans far har allerede taget æggene","Et dyr har været ved hønsegården"],"a":"Et dyr har været ved hønsegården","r":"Poteaftryk og bange høns tyder på, at et dyr, for eksempel en ræv, har været der."},
{"l":1525,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Vores skole har mange dygtige ___.'","o":["lærere","lærer","læreren","lærerne"],"a":"lærere","r":"Efter 'mange dygtige' står ubestemt flertal: lærere. 'Lærerne' betyder nogle bestemte lærere."},
{"l":1545,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning har rigtige kommaer, når Oskar fortæller, hvad han kan lide at lave?","o":["Oskar kan lide at læse tegne, og svømme.","Oskar kan lide at læse, tegne og svømme.","Oskar kan, lide at læse tegne og svømme.","Oskar kan lide, at læse tegne, og svømme."],"a":"Oskar kan lide at læse, tegne og svømme.","r":"Tre ting opremses. Kommaet står mellem de to første, og det sidste kommer efter 'og' uden komma foran."},
{"l":1565,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord har fået stort bogstav uden grund: 'Anna og Malthe fodrede deres Kanin i Hillerød.'?","o":["Anna","Malthe","Kanin","Hillerød"],"a":"Kanin","r":"På dansk får almindelige navneord lille bogstav. 'Kanin' fortæller, hvilket dyr det er, og er ikke dyrets navn."},
{"l":1585,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Han bærer krone og bor på et slot. Hvilken stavemåde er rigtig?","o":["konke","kongge","kånge","konge"],"a":"konge","r":"Ordet skrives med o og ng, selvom det lyder som å."},
{"l":1604,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg det rigtige ord: 'Du kan ___ til mig i aften, hvis du vil.'","o":["ringe","rinke","ringge","rænge"],"a":"ringe","r":"Ordet skrives med ng, fordi der ikke høres noget k."},
{"l":1623,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form passer: 'Det er ___ at spise mange grøntsager.'","o":["sunt","sundt","sund","sunnt"],"a":"sundt","r":"Efter 'det er' får tillægsordet et t. Det stumme d skal blive stående foran t'et."},
{"l":1645,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er datid af 'at flyve': 'Ørnen ___ højt over bjerget i går.'","o":["flyver","flyve","fløj","fløjet"],"a":"fløj","r":"Datid af 'at flyve' er 'fløj'. 'Fløjet' bruger man efter 'har' eller 'er'."},
{"l":1665,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er et 'rådhus'?","o":["en butik, hvor man køber råvarer","en hal, hvor man dyrker sport","et sted, hvor man venter på toget","en bygning, hvor kommunen arbejder"],"a":"en bygning, hvor kommunen arbejder","r":"På rådhuset holder kommunens ledelse til. 'Råd' betyder her en gruppe, der træffer beslutninger."},
{"l":1683,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Anna havde bagt en kage helt uden opskrift. Den var sort på den ene side og lugtede mærkeligt. Selv hunden, som ellers spiser alt, gik i en stor bue uden om den.' Hvad fortæller hundens opførsel om kagen?","o":["At den nok ikke smager godt","At den sikkert er rigtig god","At den er for stor til hunden","At den skal have mere tid i ovnen"],"a":"At den nok ikke smager godt","r":"Hunde spiser det meste, men denne hund vil ikke engang i nærheden. Det er en sjov måde at sige, at kagen er dårlig."},
{"l":1705,"g":4,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find datid af 'at gøre': 'I går ___ vi rent i klassen.'","o":["gør","gjorde","gøre","gjort"],"a":"gjorde","r":"'At gøre' er uregelmæssigt: gør, gjorde, gjort. 'Gjort' står efter 'har'."},
{"l":1725,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord mangler kommaet: 'Jeg så en ræv en hare og et rådyr.'?","o":["hare","og","ræv","rådyr"],"a":"ræv","r":"Tre dyr opremses. Mellem 'en ræv' og 'en hare' skal der komma, og foran 'og' skal der ikke komma."},
{"l":1745,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor skal anførselstegnene stå, når Clara fortæller om sin hund?","o":["Clara sagde: Min »hund er syg.«","Clara »sagde: Min hund er syg.«","»Clara sagde: Min hund er syg.«","Clara sagde: »Min hund er syg.«"],"a":"Clara sagde: »Min hund er syg.«","r":"Anførselstegnene står om alt det, Clara siger, og kun det. 'Clara sagde' er ikke en del af hendes tale."},
{"l":1765,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du låser døren op med den. Hvordan staves den?","o":["nøgle","nøjle","nøggle","nøkle"],"a":"nøgle","r":"Ordet skrives med g, selvom det lyder som j."},
{"l":1784,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er en 'knogle'?","o":["en lille muskel inde i fingeren","en af de hårde dele i skelettet","en blød del dybt inde i maven","et tykt stykke hud på knæet"],"a":"en af de hårde dele i skelettet","r":"Knoglerne er hårde og udgør tilsammen skelettet, som holder kroppen oppe."},
{"l":1803,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'I dag er det dejligt ___ med sol.'","o":["veir","væjr","vejr","vejrr"],"a":"vejr","r":"Ordet skrives med ej og slutter direkte på r, ligesom 'lejr'."},
{"l":1825,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'høj' passer: 'Ali er den ___ af alle i klassen.'","o":["højere","højest","høje","højeste"],"a":"højeste","r":"Ali sammenlignes med alle, så det skal være højeste grad. Efter 'den' får ordet -e: den højeste."},
{"l":1845,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning har kommaet rigtigt, når Liv fortæller om sin aften?","o":["Da jeg havde spist, så jeg en film.","Da jeg havde, spist så jeg en film.","Da jeg havde spist så, jeg en film.","Da, jeg havde spist så jeg en film."],"a":"Da jeg havde spist, så jeg en film.","r":"Ledsætningen er 'Da jeg havde spist'. Den står først, så kommaet skal stå lige efter 'spist'."},
{"l":1863,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Jeg er den første i køen hver dag, sagde Mikkel og skubbede sig frem. Hans lærer løftede det ene øjenbryn og pegede bag i rækken.' Hvad betyder lærerens tegn?","o":["At Mikkel skal sidde ned","At Mikkel skal bagerst i køen","At Mikkel skal gå hen til tavlen","At Mikkel har gjort det godt"],"a":"At Mikkel skal bagerst i køen","r":"Han skubbede, og læreren peger bag i rækken. Det betyder, at han skal stille sig bagerst."},
{"l":1885,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"4.a har 20 elever, og 4.b har 24. Hvilket ord passer: 'Der er ___ elever i 4.a end i 4.b.'","o":["få","færrest","færre","flere"],"a":"færre","r":"Man tæller elever, og 4.a har det laveste tal. Med 'end' hedder det 'færre'."},
{"l":1905,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Hun hedder sofie Holm og går i fjerde klasse.'?","o":["hedder","fjerde","klasse","sofie"],"a":"sofie","r":"Både fornavn og efternavn skal have stort bogstav. Her er kun efternavnet Holm skrevet rigtigt."},
{"l":1923,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Myrer arbejder sammen. Nogle henter mad, andre passer æggene, og andre igen forsvarer tuen. Ingen myre kan klare sig alene ret længe.' Hvad er hovedpointen i teksten?","o":["At myrer deler arbejdet mellem sig","At myrer er meget stærke dyr","At myrer er bedst til at finde mad","At myrer lægger mange æg om året"],"a":"At myrer deler arbejdet mellem sig","r":"Hele teksten handler om, at myrerne har hver sin opgave og er afhængige af hinanden."},
{"l":1945,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken grad af 'lang' passer: 'Min vej til skole er ___ end din.'","o":["lang","længere","længst","lange"],"a":"længere","r":"Der sammenlignes med 'end', så det er højere grad. Vokalen skifter: lang, længere, længst."},
{"l":1965,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Inden vi går skal du finde din hue.'?","o":["vi","skal","går","du"],"a":"går","r":"'Inden vi går' er en ledsætning. Den kan ikke stå alene, og når den står først, skal der komma efter den."},
{"l":1984,"g":4,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå på stregen? 'Floden er så ___, at vi må tage en båd.'","o":["bret","bredd","brej","bred"],"a":"bred","r":"Ordet ender på blødt d. Der er ét d og ingen t-lyd."},
{"l":2004,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Pelle skulle i dag sige undskyld. Han havde øvet sig i bussen, men da han stod over for Sofus, kom ordene ikke frem. Han rakte i stedet sin halve chokoladebar ud.' Hvad skal chokoladen betyde?","o":["At Pelle vil gøre det godt igen","At Pelle er træt af chokolade","At Pelle vil have noget af Sofus","At Pelle er sulten efter turen"],"a":"At Pelle vil gøre det godt igen","r":"Han kan ikke sige undskyld med ord. Chokoladen er en anden måde at sige det på."},
{"l":2022,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Karen tog sin plads på startlinjen. Hun rystede benene og trak vejret dybt. Hendes modstandere så meget større ud end på billedet.' Hvad tænker Karen nok?","o":["Hun glæder sig til frokost","Hun tvivler på, om hun kan vinde","Hun er sikker på, at hun vinder","Hun har glemt sit startnummer"],"a":"Hun tvivler på, om hun kan vinde","r":"Når modstanderne ser større ud, end hun troede, tvivler hun på sig selv. Hun er nervøs før løbet."},
{"l":2041,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Den hvide is smager tit af ___.'","o":["vanilie","vanillje","vanilje","vanilji"],"a":"vanilje","r":"Ordet skrives med j og ét l. Det slutter på e."},
{"l":2065,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Bogen er Jeppes. Hvilket ord er rigtigt: 'Jeg afleverer ___ bog til læreren.'","o":["sin","ham","han","hans"],"a":"hans","r":"Det er mig, der afleverer, men bogen er Jeppes. 'Sin' bruger man kun, når ejeren selv gør noget i sætningen, så her hedder det 'hans'."},
{"l":2085,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning skal slutte med spørgsmålstegn, selv om den ikke har et spørgeord?","o":["Har du set min hue","Jeg så din hue i går","Hun tog hue på","Huen er blå"],"a":"Har du set min hue","r":"Sætningen begynder med udsagnsordet 'har', og det viser, at det er et spørgsmål. Svaret kan være ja eller nej."},
{"l":2103,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'I gamle dage var der ikke skole for alle børn. Mange børn skulle hjælpe til på gården i stedet. Først i 1814 fik Danmark en lov om, at alle børn skulle i skole.' Hvad skete der i 1814?","o":["Børn skulle nu hjælpe på gården","Alle børn skulle nu i skole","Børn fik lov at holde fri","Skolerne blev flyttet til gårde"],"a":"Alle børn skulle nu i skole","r":"Loven betød, at alle børn skulle i skole. Det kaldes skolepligt."},
{"l":2125,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Aya skyndte ___ hjem.'","o":["hende","hun","sig","sin"],"a":"sig","r":"Udsagnsordet hedder 'at skynde sig'. Ordet 'sig' peger tilbage på Aya selv."},
{"l":2145,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Hvis du vil med skal du skynde dig.'?","o":["vil","skal","du","med"],"a":"med","r":"Ledsætningen 'Hvis du vil med' slutter efter 'med'. Derfor kommer kommaet dér."},
{"l":2164,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavemåde: 'I går ___ jeg alle mine lektier færdige.'","o":["gjorde","gjorte","gjode","gørde"],"a":"gjorde","r":"Datid af 'gøre' begynder med gj og ender på -de."},
{"l":2184,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Bodil hængte et fuglebræt op midt på plænen. I en uge kom der ingen fugle. Så flyttede hun brættet hen til busken, og næste morgen sad der tre spurve på det. Bagefter hentede hun mere frø.' Hvilken ændring ser ud til at have fået fuglene til at komme?","o":["At Bodil fyldte mere frø på brættet","At brættet kom tæt på busken","At brættet havde hængt der i en uge","At brættet stod frit midt på plænen"],"a":"At brættet kom tæt på busken","r":"Spurvene kom, lige efter at brættet var flyttet. Det ekstra frø er fristende, men det hentede Bodil først bagefter."},
{"l":2202,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mine forældre sagde nej til et trommesæt. Så jeg byggede selv ét af spande og låg. Efter en uge købte de høreværn til hele familien, og efter to uger kom der et elektrisk trommesæt, som man spiller på med høretelefoner.' Hvorfor købte forældrene trommesættet?","o":["Barnet havde fødselsdag","Barnet var blevet rigtig dygtig","Det larmede mindre end spandene","Det var på udsalg i butikken"],"a":"Det larmede mindre end spandene","r":"Høreværnene viser, at spandene larmede. Med høretelefoner kan barnet spille, uden at resten af familien hører det."},
{"l":2221,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Alle ___ i vores gade har rødt tag.'","o":["huserne","husenne","husen","husene"],"a":"husene","r":"Flertal er 'huse', og bestemt form får -ne. Der er ét n."},
{"l":2245,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvad er udsagnsleddet: 'Min farmor har bagt boller i dag.'","o":["har bagt","Min farmor","boller","i dag"],"a":"har bagt","r":"Udsagnsleddet kan bestå af to udsagnsord. Her hører 'har' og 'bagt' sammen."},
{"l":2265,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'Min Mor hedder Eva og bor i Esbjerg.'?","o":["Min","Mor","Eva","Esbjerg"],"a":"Mor","r":"'mor' er her ikke et navn, men fortæller, hvem Eva er. Eva er navnet, og det har stort bogstav."},
{"l":2283,"g":4,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vores kat er ikke særlig modig. Den stikker af fra støvsugeren og gemmer sig for naboens hamster. Alligevel står den hver aften på vindueskarmen og vrisser ad duerne, når ruden er lukket.' Hvorfor vrisser katten kun, når ruden er lukket?","o":["Fordi duerne ikke kan høre den","Fordi den er sulten om aftenen","Fordi den er tryg bag glasset","Fordi den er vant til duerne"],"a":"Fordi den er tryg bag glasset","r":"Katten er ikke modig, men bag en lukket rude kan duerne ikke nå den. Så tør den godt."},
{"l":2302,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'hyppig'?","o":["gammel","svag","stille","sjælden"],"a":"sjælden","r":"Det, der er hyppigt, sker ofte. Det, der er sjældent, sker kun en gang imellem."},
{"l":2325,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'generøs'?","o":["nærig","doven","klog","frygtsom"],"a":"nærig","r":"En generøs person giver gerne, mens en nærig person holder på sine ting og sine penge."},
{"l":2345,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om filmen mangler et komma?","o":["Efter filmen gik vi hjem.","Da filmen var slut gik vi hjem.","Vi så en film og gik hjem.","Bagefter gik vi hjem."],"a":"Da filmen var slut gik vi hjem.","r":"'Da filmen var slut' er en ledsætning, der står først, så der skal komma efter 'slut'. 'Efter filmen' er ikke en ledsætning, for der er intet udsagnsord."},
{"l":2364,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"En person, der passer patienter på hospitalet sammen med lægerne. Find den rigtige stavemåde.","o":["syjeplejerske","sygeplejeske","sygeplejerske","sygepleierske"],"a":"sygeplejerske","r":"Ordet består af 'syge' og 'plejerske'. Husk r'et foran -ske."},
{"l":2383,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"En, der går i skole og lærer noget. Hvordan staves det?","o":["ellev","elew","eleev","elev"],"a":"elev","r":"Ordet har ét l og ét e i slutningen. Det ender på v."},
{"l":2402,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Faget, hvor I laver øvelser på måtter og i ribberne. Vælg den rigtige stavemåde.","o":["gymnastik","gymnastig","gynnastik","gymnastick"],"a":"gymnastik","r":"Ordet skrives med y og m foran n. Det slutter på -ik."},
{"l":2423,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør to personer, der 'forhandler'?","o":["De sælger varer til hinanden.","De prøver at blive enige.","De skændes højt om det.","De holder op med at tale."],"a":"De prøver at blive enige.","r":"Ved en forhandling taler man sammen, indtil man finder en løsning, som begge kan acceptere."},
{"l":2442,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mens læreren gennemgik opgaven, kiggede Louise ud ad vinduet. Hun sad i klassen, men hendes hoved var allerede på vej til stranden. I morgen begyndte sommerferien.' Hvad betyder det, at hendes hoved var på vej til stranden?","o":["At hun har ondt i hovedet","At hun skal gå til stranden nu","At hun tænker på sommerferien","At hun vil have en ny plads"],"a":"At hun tænker på sommerferien","r":"Her er hovedet et billede på tankerne. Hun sidder i klassen, men hun tænker på ferien."},
{"l":2461,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"I hvilken sætning er 'bager' et udsagnsord?","o":["Vi gik hen til en bager.","Bager Jensen har åbent.","Vores bager sælger kager.","Min far bager boller."],"a":"Min far bager boller.","r":"Kun her fortæller 'bager', hvad nogen gør. I de andre sætninger er det en person."},
{"l":2483,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en 'vaccination'?","o":["Den beskytter kroppen mod en sygdom.","Den fjerner smerten fra en brækket arm.","Den gør dine tænder stærke og hvide.","Den hjælper dig med at sove om natten."],"a":"Den beskytter kroppen mod en sygdom.","r":"En vaccine lærer kroppen at kæmpe mod en sygdom, før man overhovedet bliver syg."},
{"l":2505,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det at 'ramme hovedet på sømmet'?","o":["at slå meget hårdt med en stor hammer","at sige noget, der passer helt præcist","at slå sit hoved mod noget hårdt","at lave en lille fejl, man ikke opdager"],"a":"at sige noget, der passer helt præcist","r":"En god tømrer rammer sømmet lige på hovedet. På samme måde kan man sige noget, der passer helt præcist."},
{"l":2523,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Eiffeltårnet blev bygget til en stor udstilling i Paris i 1889. Det skulle kun stå i tyve år og derefter rives ned. Alligevel står det der stadig i dag.' Hvad er det overraskende i teksten?","o":["At tårnet blev bygget i 1889","At der var en stor udstilling","At tårnet stadig står der i dag","At tårnet står i Paris"],"a":"At tårnet stadig står der i dag","r":"Ordet 'alligevel' viser modsætningen: Tårnet skulle rives ned efter tyve år, men det står der stadig."},
{"l":2543,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket navneord hører til tillægsordet 'tyk'?","o":["tyveri","tyggegummi","tyngde","tykkelse"],"a":"tykkelse","r":"Hvor tyk en bog er, kalder vi dens tykkelse. 'Tyngde' lyder lignende, men kommer af 'tung'."},
{"l":2563,"g":4,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Det store grå dyr med snabel. Hvilken stavemåde er rigtig?","o":["elefant","ellefant","elefan","elevant"],"a":"elefant","r":"Ordet har ét l og skrives med f. Det slutter på -ant."},
{"l":2582,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"En sort og hvid fugl, der ikke kan flyve, men svømmer godt. Hvordan staves den?","o":["pinguin","pingvin","pinkvin","pingvind"],"a":"pingvin","r":"Ordet skrives med ng og v, og der er intet d til sidst."},
{"l":2603,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'hovmodig'?","o":["modløs","frygtsom","storsnudet","beskeden"],"a":"storsnudet","r":"En hovmodig person ser ned på andre, ligesom en storsnudet. 'Beskeden' er næsten det modsatte."},
{"l":2622,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Mange honningbier er i fare. Hvis de forsvinder, rammer det også os. Mange af de planter, vi spiser, bliver nemlig bestøvet af bier.' Hvorfor er det et problem for mennesker, hvis bier forsvinder?","o":["Fordi vi ikke kan få nok sukker","Fordi bier passer på vores haver","Fordi bier spiser skadelige insekter","Fordi bier hjælper de planter, vi spiser"],"a":"Fordi bier hjælper de planter, vi spiser","r":"Teksten forklarer, at mange af de planter, vi spiser, bliver bestøvet af bier. Uden bier får vi færre af dem."},
{"l":2641,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Tillægsordet skal passe til 'vandet'. Hvilken sætning er rigtig?","o":["Vandet i søen var koldt.","Vandet i søen var kold.","Vandet i søen var kolde.","Vandet i søen var kulde."],"a":"Vandet i søen var koldt.","r":"'Vandet' er et et-ord, så tillægsordet får -t, også når det står efter navneordet."},
{"l":2664,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Et lille barn er 'afhængigt' af sine forældre. Hvad betyder det?","o":["at det ligner dem meget","at det har brug for dem","at det ikke kan lide dem","at det hænger på deres arm"],"a":"at det har brug for dem","r":"Den, der er afhængig af nogen, kan ikke klare sig uden dem. Det modsatte er uafhængig."},
{"l":2685,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning om konkurrencen har kommaet det rigtige sted?","o":["Hvis jeg vinder, konkurrencen giver jeg is til alle.","Hvis jeg vinder konkurrencen giver, jeg is til alle.","Hvis jeg vinder konkurrencen, giver jeg is til alle.","Hvis, jeg vinder konkurrencen giver jeg is til alle."],"a":"Hvis jeg vinder konkurrencen, giver jeg is til alle.","r":"Ledsætningen slutter med 'konkurrencen', for det hører med til det, der skal vindes. Kommaet står efter hele ledsætningen."},
{"l":2703,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ingen kunne forstå, at Aisha ikke blev træt. Hun løb den sidste omgang lige så hurtigt som den første. Hun havde trænet hver dag i et år uden at sige det til nogen.' Hvad forklarer den sidste sætning?","o":["Hvorfor hun ikke sagde det til nogen","Hvorfor hendes træner var sur","Hvorfor hun tabte til sidst","Hvorfor hun havde så mange kræfter"],"a":"Hvorfor hun havde så mange kræfter","r":"Den sidste sætning forklarer det, der undrede de andre: Hun havde trænet i hemmelighed."},
{"l":2724,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at noget er 'bæredygtigt'?","o":["at det kan blive ved uden at skade naturen","at det er stærkt nok til at bære noget tungt","at det kan købes i alle butikker i landet","at det vokser meget hurtigt om foråret"],"a":"at det kan blive ved uden at skade naturen","r":"Hvis man fisker bæredygtigt, tager man kun så mange fisk, at der stadig er nok til næste år. Ordet handler ikke om at bære ting."},
{"l":2744,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Du kan lyse med den i mørket. Hvilket ord er stavet rigtigt?","o":["lommelykte","lommelygte","lomelygte","lomme lygte"],"a":"lommelygte","r":"Ordet består af 'lomme' og 'lygte'. Det skrives i ét ord, og lygte skrives med gt."},
{"l":2763,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"I tivoli sidder du på den, og den snurrer rundt. Vælg den rigtige stavemåde.","o":["karusel","karrussel","karrusel","karusell"],"a":"karrusel","r":"Ordet har to r'er, ét s og ét l."},
{"l":2784,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vi taler ikke om din fødselsdag endnu, sagde far til Lucas og blinkede. Næste morgen stod der en stor kasse med huller i låget ude i gangen. Noget derinde pippede svagt.' Hvad antyder det?","o":["At far har glemt fødselsdagen","At der er en fløjte i kassen","At far vil stille kassen i haven","At Lucas skal have et dyr i gave"],"a":"At Lucas skal have et dyr i gave","r":"Far blinker, kassen har huller, og noget pipper derinde. Huller i låget giver luft, så der må være et dyr i kassen."},
{"l":2802,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Han løb hele vejen med brevet. Da han endelig stod foran postkassen, tøvede han. Hvad nu hvis hun grinede af ham? Så stak han det langsomt tilbage i lommen.' Hvad er der nok i brevet?","o":["Noget, der betyder meget for ham","En regning til hans far","En indbydelse til hele klassen","En opgave til skolen"],"a":"Noget, der betyder meget for ham","r":"Han er bange for, at hun vil grine. Så må det være noget, der betyder meget for ham."},
{"l":2822,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder det, at man er 'våd bag ørerne'?","o":["at man lige har været i bad","at man er ung og uden erfaring","at man er blevet fanget i regnen","at man er meget forkølet"],"a":"at man er ung og uden erfaring","r":"Vendingen bruges om en, der er ny og ikke har prøvet så meget endnu. Den handler ikke om vand."},
{"l":2845,"g":4,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord hører ikke til ordfamilien om 'køre'?","o":["kørsel","køretøj","køkken","kørekort"],"a":"køkken","r":"'Køkken' begynder med de samme bogstaver, men handler om madlavning. De andre har alle noget at gøre med at køre."},
{"l":2862,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Asta stod ved lågen og kiggede ned ad vejen. Hver gang en bil kørte forbi, rejste hun sig op på tæerne. Mormor havde lovet at komme klokken tre, og nu var klokken næsten halv fire. Asta bed sig i læben og kiggede på sit ur igen.' Hvordan har Asta det?","o":["Hun er træt og vil gerne ind","Hun er vred på sin mormor","Hun er glad for at være alene","Hun er utålmodig og lidt urolig"],"a":"Hun er utålmodig og lidt urolig","r":"Asta står og venter, tjekker uret og bider sig i læben. Det viser, at ventetiden gør hende urolig, selvom teksten ikke siger det direkte."},
{"l":2882,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord binder de to dele af sætningen sammen: 'Jeg ville gerne cykle, men mit dæk var fladt.'","o":["men","gerne","mit","fladt"],"a":"men","r":"'Men' er et bindeord. Det forbinder to sætninger og viser en modsætning mellem dem."},
{"l":2904,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find grundleddet: 'Den gamle hund sover i kurven.'","o":["sover","Den gamle hund","i kurven","sover i kurven"],"a":"Den gamle hund","r":"Spørg: Hvem sover? Svaret er 'den gamle hund', og hele den ordgruppe er grundleddet."},
{"l":2922,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord har fået stort bogstav uden grund: 'Naja fra Grønland fejrer Nytår i Aalborg.'?","o":["Naja","Grønland","Nytår","Aalborg"],"a":"Nytår","r":"Højtider som nytår og jul skrives med lille. De tre andre ord er navne på en person, et land og en by."},
{"l":2941,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord mangler kommaet i opremsningen: 'Vi har været i Sverige Norge, Finland og Island.'?","o":["Norge","Finland","Island","Sverige"],"a":"Sverige","r":"Alle lande i opremsningen skal skilles med komma, undtagen foran 'og'. Efter 'Norge' står kommaet allerede."},
{"l":2960,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket tegn skal stå på den tomme plads: 'Mikkel undrede sig og sagde___ »Hvem har flyttet min taske?«'?","o":["kolon","punktum","spørgsmålstegn","udråbstegn"],"a":"kolon","r":"Kolon viser, at nu kommer det, Mikkel siger. Det står lige foran anførselstegnet."},
{"l":2980,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad skal der stå på stregen: 'Far blev så ___, da Yusuf spillede sin solo, at han fik tårer i øjnene.'","o":["forvirret","rørt","hidsig","gnaven"],"a":"rørt","r":"Man er rørt, når noget går lige ind i hjertet, og man næsten må græde af glæde."},
{"l":3002,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'lodret'?","o":["stejl","krum","vandret","tyk"],"a":"vandret","r":"Lodret går lige op og ned som en flagstang. Vandret ligger fladt som overfladen på stille vand."},
{"l":3017,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'Bussen kom for sent. derfor nåede vi ikke filmen.'?","o":["sent","nåede","filmen","derfor"],"a":"derfor","r":"Efter et punktum begynder en ny sætning. Det gælder også, selv om den hænger sammen med sætningen før."},
{"l":3040,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad var en 'træl' i vikingetiden?","o":["en slave, der skulle arbejde for sin herre","en købmand, der sejlede til fjerne lande","en høvding, der styrede en lille bygd","en digter, der fortalte om store slag"],"a":"en slave, der skulle arbejde for sin herre","r":"Trælle var ikke frie. De tilhørte en herre og havde næsten ingen rettigheder."},
{"l":3058,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord er et stedord: 'Kan du hjælpe mig med opgaven?'","o":["kan","mig","hjælpe","opgaven"],"a":"mig","r":"'Mig' står i stedet for navnet på den, der taler. Det er et personligt stedord."},
{"l":3080,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find bindeordet: 'Vil du have æble eller pære?'","o":["have","vil","eller","pære"],"a":"eller","r":"'Eller' forbinder to muligheder. Det er et bindeord."},
{"l":3100,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad laver en 'arkæolog'?","o":["undersøger stjerner og fjerne planeter","tegner kort over byer og landeveje","studerer dyr, der lever dybt i havet","graver gamle ting op og undersøger dem"],"a":"graver gamle ting op og undersøger dem","r":"Arkæologer finder spor fra fortiden i jorden, for eksempel potteskår og knogler, og fortæller, hvordan folk levede."},
{"l":3122,"g":5,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gjorde drengene, da de 'tog benene på nakken'?","o":["De løb væk i fuld fart","De lavede kolbøtter i gymnastik","De gik tidligt i seng","De spiste deres mad stående"],"a":"De løb væk i fuld fart","r":"Vendingen betyder at skynde sig væk. Forestil dig, at man løber så stærkt, at benene næsten når op til nakken."},
{"l":3145,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør man, når man 'holder tand for tunge'?","o":["Man bider sig selv i tungen","Man tier stille med en hemmelighed","Man går til tandlægen til tiden","Man lærer et nyt sprog udenad"],"a":"Man tier stille med en hemmelighed","r":"Tænderne holder tungen tilbage, så man ikke siger noget. Vendingen betyder, at man ikke røber noget."},
{"l":3160,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Vildsvin spiser både rødder, orme og små dyr. Hvad kaldes sådan et dyr?","o":["et rovdyr","en planteæder","en altæder","en nedbryder"],"a":"en altæder","r":"En altæder spiser både planter og dyr. Et rovdyr lever mest af kød, og en planteæder lever kun af planter."},
{"l":3181,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'På vikingecenteret i Sønderholt kan man opleve, hvordan vikinger levede. Man kan smage mad over bål og prøve at skyde med bue. Efter min mening er det langt bedre end at læse om vikingerne i en bog. Centeret holder åbent fra maj til oktober.' Hvilken sætning viser skribentens egen mening?","o":["Man kan smage mad over bål","Centeret holder åbent fra maj til oktober","Man kan prøve at skyde med bue","Det er langt bedre end at læse om vikingerne"],"a":"Det er langt bedre end at læse om vikingerne","r":"Ordene 'efter min mening' og 'langt bedre' viser, at det er skribentens vurdering."},
{"l":3201,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt her? 'Tandlægen roste mine rene, ___ tænder.'","o":["hvide","vide","hvidde","hvite"],"a":"hvide","r":"Farven skrives med stumt h foran v. Uden h betyder ordet noget helt andet."},
{"l":3220,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Jonas 'overtalte' sin søster til at gå med. Hvad gjorde han?","o":["Han talte så højt, at alle kunne høre det","Han snakkede, til hun sagde ja","Han hentede hende på skolen efter timerne","Han glemte helt at spørge hende om det"],"a":"Han snakkede, til hun sagde ja","r":"At overtale nogen er at få dem til at ændre mening ved at tale med dem. Ordet har intet at gøre med at tale højt."},
{"l":3242,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kaldes det, når grønne planter bruger sollys til at lave sukker og ilt?","o":["fordampning","nedbrydning","fotosyntese","forbrænding"],"a":"fotosyntese","r":"Foto betyder lys, og syntese betyder at sætte sammen. Planten laver sin egen næring ved hjælp af lyset."},
{"l":3257,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord er det modsatte af 'fordel' i sætningen: 'Det er en fordel at være høj til basketball.'","o":["gevinst","mulighed","regel","ulempe"],"a":"ulempe","r":"En fordel hjælper dig, og en ulempe gør det sværere for dig. Gevinst ligger tæt på fordel, altså ikke det modsatte."},
{"l":3280,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder næsten det samme som 'enormt' her: 'Blåhvalen er et enormt dyr.'","o":["kæmpestort","farligt","sjældent","hurtigt"],"a":"kæmpestort","r":"Enorm betyder meget stor. Blåhvalen kan godt også være sjælden, men det er ikke det, ordet enorm siger."},
{"l":3300,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form er den rigtige? 'Mange ___ fra byen var på havet i nat.'","o":["fisker","fiskere","fiskerer","fiskre"],"a":"fiskere","r":"'Mange' viser, at der er flere, så navneordet skal stå i flertal med -ere."},
{"l":3317,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad bruger du en 'adgangskode' til?","o":["At komme ind til en koncert med en billet","At låse din cykel fast ved et cykelstativ","At logge ind på noget, som kun du må bruge","At sende en hemmelig besked til en ven"],"a":"At logge ind på noget, som kun du må bruge","r":"En adgangskode er et hemmeligt ord eller tal, der giver dig adgang, f.eks. til din konto."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
